/* @autogenerated */
package net.civeira.phylax.feature.oauth.mfa.infrastructure.driven;

import java.util.Locale;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import dev.samstevens.totp.code.DefaultCodeGenerator;
import dev.samstevens.totp.code.HashingAlgorithm;
import dev.samstevens.totp.time.SystemTimeProvider;
import net.civeira.phylax.feature.access.usermfaenrollment.domain.UserMfaEnrollment;
import net.civeira.phylax.feature.access.usermfaenrollment.domain.gateway.UserMfaEnrollmentFilter;
import net.civeira.phylax.feature.identity.user.domain.UserReference;
import net.civeira.phylax.feature.oauth.mfa.domain.PublicLoginMfaBuildResponse;
import net.civeira.phylax.feature.oauth.mfa.infrastructure.OtpMfaService;
import net.civeira.phylax.feature.oauth.user.infrastructure.ActiveUserFindService;
import net.civeira.phylax.testing.sql.OidcRepositories;

/** The enrollment of the second factor stored with the generated repositories on h2. */
class UserMfaConfigAdapterUnitTest {
  private OidcRepositories store;
  private UserMfaConfigAdapter mfa;
  private String alice;

  @BeforeEach
  void setUp() {
    store = new OidcRepositories();
    String tenant = store.tenant("acme");
    alice = store.user(tenant, "alice", "alice@acme.test");
    mfa = new UserMfaConfigAdapter(new OtpMfaService(),
        new ActiveUserFindService(store.tenants(), store.users()), store.userWriter(),
        store.mfaEnrollments(), store.secrets());
  }

  private String pendingSeed() {
    UserMfaEnrollment enrollment = store.mfaEnrollments()
        .findForUpdate(UserMfaEnrollmentFilter.builder().user(UserReference.of(alice)).build())
        .orElseThrow();
    return enrollment.getPendingSeedValue().plainValueWith(store.secrets(), enrollment.getUid())
        .orElseThrow();
  }

  private static String otp(String seed) throws Exception {
    long window = Math.floorDiv(new SystemTimeProvider().getTime(), 30);
    return new DefaultCodeGenerator(HashingAlgorithm.SHA256).generate(seed, window);
  }

  @Test
  @DisplayName("A new enrollment gives a qr image and keeps the pending seed sealed")
  void new_enrollment() {
    PublicLoginMfaBuildResponse response =
        mfa.configurationForNewMfa("acme", "alice", Locale.ENGLISH);

    Assertions.assertTrue(response.isRequiresImage());
    Assertions.assertTrue(response.getImage().startsWith("data:image/png;base64,"));
    String seed = pendingSeed();
    String stored = store.value("SELECT pending_seed FROM access_user_mfa_enrollment");
    Assertions.assertNotEquals(seed, stored, "The pending seed is not stored in clear");

    mfa.configurationForNewMfa("acme", "alice", Locale.ENGLISH);
    Assertions.assertEquals(seed, pendingSeed(), "A pending enrollment reuses its seed");
    Assertions.assertEquals(1, store.db().count("access_user_mfa_enrollment", null));
  }

  @Test
  @DisplayName("A valid code confirms the seed on the user and clears the enrollment")
  void confirm() throws Exception {
    mfa.configurationForNewMfa("acme", "alice", Locale.ENGLISH);
    String seed = pendingSeed();

    String code = otp(seed);
    String wrong = String.format("%06d", (Integer.parseInt(code) + 500_000) % 1_000_000);

    Assertions.assertFalse(mfa.verifyNewOtp("acme", "alice", wrong));
    Assertions.assertNotNull(store.value("SELECT pending_seed FROM access_user_mfa_enrollment"),
        "A wrong code keeps the enrollment pending");
    Assertions.assertTrue(mfa.verifyNewOtp("acme", "alice", code));

    Assertions.assertEquals("TRUE",
        store.value("SELECT use_second_factors FROM identity_user WHERE uid = '" + alice + "'")
            .toUpperCase());
    Assertions.assertNotNull(
        store.value("SELECT second_factor_seed FROM identity_user WHERE uid = '" + alice + "'"));
    Assertions.assertNull(store.value("SELECT pending_seed FROM access_user_mfa_enrollment"));
    Assertions.assertFalse(mfa.verifyOtp("acme", "alice", otp(seed)),
        "Without a pending enrollment there is nothing to confirm");
  }

  @Test
  @DisplayName("Unknown users get neither image nor confirmation")
  void unknown_user() {
    Assertions.assertNull(mfa.configurationForNewMfa("acme", "bob", Locale.ENGLISH).getImage());
    Assertions.assertFalse(mfa.verifyOtp("acme", "bob", "123456"));
    Assertions.assertFalse(mfa.verifyNewOtp("acme", "alice", "123456"),
        "Without enrollment the code is not valid");
    mfa.storeSeed("acme", "alice", "seed");
    Assertions.assertEquals(0, store.db().count("access_user_mfa_enrollment", null));
  }
}
